package dev.builtbyahnaf.memomint.domain.model;

/**
 * Classifies the kind of derived context stored in a ContextRecord.
 *
 * <p>Context records are generated representations of a memory's content — they aid retrieval
 * but must never overwrite or replace the original user text (FR-03). Each context type has
 * a different source, format, and regeneration cost.</p>
 *
 * <p>Stored as the enum name string in the database.</p>
 */
public enum ContextType {

    /**
     * A short human-readable summary of the memory.
     * Generated by local deterministic logic; not user-supplied.
     */
    SUMMARY,

    /**
     * A set of searchable keywords extracted or derived from the memory text.
     * Used to improve recall for synonym and partial-match queries.
     */
    KEYWORDS,

    /**
     * Structured entity information: item names, locations, quantities, dates.
     * Extracted by local rules; uncertain extractions must not be marked as user-confirmed.
     */
    ENTITIES,

    /**
     * Full or chunked text extracted from an indexed document.
     * Created during document indexing (Phase 4); stored here to keep it searchable.
     */
    DOCUMENT_CONTENT
}
